def hi_row(slug, n, hi, s=.3, y=120):
    o = ''
    for i in range(n):
        x, yy = round(30 + i * 140 / (n - 1)), round(40 + i * 120 / (n - 1))
        if i == hi:
            o += E(x, yy, 38, 24, '#FFE08A', 0)
        o += S(x, yy + 22, 30, 4) + thing(slug, x, yy, s)
    return o

def kid_row(n, hi=None, y=180):
    return peg_row(n, hi, y)

